      var leftX = tipX - wing * Math.cos(angle - 0.5);
      var leftY = tipY - wing * Math.sin(angle - 0.5);
      var rightX = tipX - wing * Math.cos(angle + 0.5);
      var rightY = tipY - wing * Math.sin(angle + 0.5);
