    var rt = lensTarget(st.frameShown < 0 ? Math.max(0, st.t) : st.frameShown / TL.fps);
    var kp = 1 - Math.exp(-dt * 26);
    var kr = 1 - Math.exp(-dt * 9);
    var nx = st.lx + (st.px - st.lx) * kp;
    var ny = st.ly + (st.py - st.ly) * kp;
    var nr = st.r + (rt - st.r) * kr;
