    function tick(now){frame=0;if(!visible||document.hidden||isBrain&&!menu.open)return;if(!last||now-last>40){time+=last?Math.min(80,now-last):0;last=now;draw();}if(!reduced.matches)frame=requestAnimationFrame(tick);}
